import { booleanAttribute, ChangeDetectionStrategy, Component, inject, input, numberAttribute, TemplateRef, viewChild, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import type { SplitterPanelPassThrough } from 'primeng/types/splitter';
import { SplitterStyle } from './style/splitterstyle';

/**
 * SplitterPanel is a helper component for Splitter, used to define a single resizable panel
 * together with its size constraints (min/max size, collapsible behavior).
 * @group Components
 */
@Component({
    selector: 'p-splitterpanel, p-splitter-panel',
    standalone: true,
    template: `
        <ng-template #content>
            <ng-content></ng-content>
        </ng-template>
    `,
    encapsulation: ViewEncapsulation.None,
    changeDetection: ChangeDetectionStrategy.OnPush,
    hostDirectives: [Bind],
    providers: [SplitterStyle, { provide: PARENT_INSTANCE, useExisting: SplitterPanel }]
})
export class SplitterPanel extends BaseComponent<SplitterPanelPassThrough> {
    componentName = 'SplitterPanel';

    bindDirectiveInstance = inject(Bind, { self: true });

    /**
     * Initial size of the panel relative to 100%.
     * @group Props
     */
    size = input<number | undefined>(undefined, { transform: (value: unknown) => (value == null ? undefined : numberAttribute(value)) });

    /**
     * Minimum size of the panel relative to 100%.
     * @defaultValue 0
     * @group Props
     */
    minSize = input(0, { transform: numberAttribute });

    /**
     * Maximum size of the panel relative to 100%.
     * @defaultValue 100
     * @group Props
     */
    maxSize = input(100, { transform: numberAttribute });

    /**
     * When enabled, the panel can collapse below its `minSize` down to `collapsedSize`.
     * @defaultValue false
     * @group Props
     */
    collapsible = input(false, { transform: booleanAttribute });

    /**
     * Size of the panel when collapsed, relative to 100%.
     * @defaultValue 0
     * @group Props
     */
    collapsedSize = input(0, { transform: numberAttribute });

    /**
     * @ignore
     * Content of the panel, stamped by the parent Splitter into the panel wrapper.
     */
    contentTemplate = viewChild<TemplateRef<any>>('content');

    /**
     * @ignore
     * `class`/`style` set directly on the `<p-splitterpanel>` element are forwarded by the parent
     * Splitter onto the panel it renders, so authors can style the panel inline as expected.
     */
    get hostClass(): string {
        return this.el.nativeElement.className;
    }

    get hostStyle(): string | null {
        return this.el.nativeElement.getAttribute('style');
    }

    _componentStyle = inject(SplitterStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
