import { isPlatformBrowser, NgTemplateOutlet } from '@angular/common';
import { booleanAttribute, ChangeDetectionStrategy, Component, computed, contentChildren, effect, ElementRef, inject, input, NgModule, numberAttribute, output, signal, TemplateRef, untracked, ViewEncapsulation } from '@angular/core';
import { isRTL } from '@primeuix/utils';
import { SharedModule } from 'primeng/api';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { Nullable, VoidListener } from 'primeng/ts-helpers';
import type { CSSProperties } from 'primeng/types/shared';
import type { SplitterCollapseEvent, SplitterLayout, SplitterPassThrough, SplitterResizeEndEvent, SplitterResizeEvent, SplitterResizeStartEvent, SplitterStateStorage } from 'primeng/types/splitter';
import { SplitterPanel } from './splitterpanel';
import { SplitterStyle } from './style/splitterstyle';

/**
 * Runtime configuration of a panel, resolved either from a SplitterPanel component or from the
 * array-based inputs (minSizes/panelSizes) for backward compatibility.
 */
interface SplitterPanelMeta {
    minSize: number;
    maxSize: number;
    collapsible: boolean;
    collapsedSize: number;
    size: number | undefined;
}

interface SplitterPanelInfo extends SplitterPanelMeta {
    index: number;
    collapsed: boolean;
}

/**
 * Splitter is utilized to separate and resize panels.
 * @group Components
 */
@Component({
    selector: 'p-splitter',
    standalone: true,
    imports: [NgTemplateOutlet, SharedModule, BindModule],
    template: `
        @for (panel of panels(); track $index; let i = $index) {
            <div
                [pBind]="ptm('panel')"
                [class]="panelClass()[i]"
                [style]="panelInlineStyle()[i]"
                [style.flex]="panelFlex()[i]"
                [style.overflow]="'hidden'"
                [style.min-width]="layout() === 'horizontal' ? '0' : null"
                [style.min-height]="layout() === 'vertical' ? '0' : null"
                tabindex="-1"
                [attr.data-index]="i"
                [attr.data-collapsed]="collapsed()[i] ? '' : null"
                [attr.data-resizing]="isResizing() && resizingIndex() === i ? '' : null"
            >
                <ng-container *ngTemplateOutlet="panel"></ng-container>
            </div>
            @if (i !== panels().length - 1) {
                <div
                    [pBind]="ptm('gutter')"
                    [class]="cx('gutter')"
                    role="separator"
                    [attr.tabindex]="disabled() ? -1 : 0"
                    [attr.aria-orientation]="layout()"
                    [attr.aria-valuenow]="prevSize"
                    [attr.aria-valuemin]="round(panelMetas()[i]?.minSize)"
                    [attr.aria-valuemax]="round(100 - (panelMetas()[i + 1]?.minSize ?? 0))"
                    [attr.aria-disabled]="disabled() || null"
                    [attr.data-orientation]="layout()"
                    [attr.data-resizing]="isResizing() && resizingIndex() === i ? '' : null"
                    [attr.data-disabled]="disabled() ? '' : null"
                    [style]="gutterInlineStyle()"
                    (pointerdown)="onGutterPointerDown($event, i)"
                    (keyup)="onGutterKeyUp($event)"
                    (keydown)="onGutterKeyDown($event, i)"
                >
                    <div [pBind]="ptm('gutterHandle')" [class]="cx('gutterHandle')" [attr.data-orientation]="layout()" [attr.data-resizing]="isResizing() && resizingIndex() === i ? '' : null"></div>
                </div>
            }
        }
    `,
    encapsulation: ViewEncapsulation.None,
    changeDetection: ChangeDetectionStrategy.OnPush,
    host: {
        '[class]': 'rootClass()',
        '[attr.data-orientation]': 'layout()',
        '[attr.data-resizing]': 'dataResizing()',
        '[attr.data-disabled]': "disabled() ? '' : null",
        '[attr.data-p]': 'dataP()'
    },
    providers: [SplitterStyle, { provide: PARENT_INSTANCE, useExisting: Splitter }],
    hostDirectives: [Bind]
})
export class Splitter extends BaseComponent<SplitterPassThrough> {
    componentName = 'Splitter';

    bindDirectiveInstance = inject(Bind, { self: true });

    /**
     * Style class of the component.
     * @group Props
     */
    styleClass = input<string>();

    /**
     * Style class of the panel.
     * @group Props
     */
    panelStyleClass = input<string>();

    /**
     * Inline style of the panel.
     * @group Props
     */
    panelStyle = input<CSSProperties>();

    /**
     * Defines where a stateful splitter keeps its state, valid values are 'session' for sessionStorage and 'local' for localStorage.
     * @group Props
     */
    stateStorage = input<SplitterStateStorage>('session');

    /**
     * Storage identifier of a stateful Splitter.
     * @group Props
     */
    stateKey = input<string | null>(null);

    /**
     * Orientation of the panels. Valid values are 'horizontal' and 'vertical'.
     * @group Props
     */
    layout = input<SplitterLayout>('horizontal');

    /**
     * Size of the divider in pixels.
     * @group Props
     */
    gutterSize = input(1, { transform: numberAttribute });

    /**
     * Step factor to increment/decrement the size of the panels while pressing the arrow keys.
     * @group Props
     */
    step = input(5, { transform: numberAttribute });

    /**
     * Minimum size of the elements relative to 100%. Used when panels are defined via `#panel` templates;
     * when SplitterPanel components are used, the per-panel `minSize` input takes precedence.
     * @group Props
     */
    minSizes = input<number[]>([]);

    /**
     * Size of the elements relative to 100%. Used when panels are defined via `#panel` templates;
     * when SplitterPanel components are used, the per-panel `size` input takes precedence.
     * @group Props
     */
    panelSizes = input<number[]>([]);

    /**
     * When present, it disables the component and prevents resizing.
     * @defaultValue false
     * @group Props
     */
    disabled = input(false, { transform: booleanAttribute });

    /**
     * Callback to invoke when resize ends.
     * @param {SplitterResizeEndEvent} event - Custom panel resize end event
     * @group Emits
     */
    onResizeEnd = output<SplitterResizeEndEvent>();

    /**
     * Callback to invoke when resize starts.
     * @param {SplitterResizeStartEvent} event - Custom panel resize start event
     * @group Emits
     */
    onResizeStart = output<SplitterResizeStartEvent>();

    /**
     * Callback to invoke continuously while a gutter is being dragged.
     * @param {SplitterResizeEvent} event - Custom panel resize event
     * @group Emits
     */
    onResize = output<SplitterResizeEvent>();

    /**
     * Callback to invoke when a collapsible panel collapses or expands.
     * @param {SplitterCollapseEvent} event - Custom collapse event
     * @group Emits
     */
    onCollapse = output<SplitterCollapseEvent>();

    /**
     * Panels declared via SplitterPanel components.
     * @ignore
     */
    panelComponents = contentChildren(SplitterPanel);

    /**
     * Panels declared via `<ng-template #panel>` (backward compatible API).
     * @ignore
     */
    panelChildren = contentChildren<TemplateRef<void>>('panel');

    /**
     * Resolved panel content templates, sourced from SplitterPanel components when present,
     * otherwise from `#panel` templates.
     */
    panels = computed<TemplateRef<any>[]>(() => {
        const components = this.panelComponents();

        if (components && components.length) {
            const templates = components.map((panel) => panel.contentTemplate());
            return templates.every((template): template is TemplateRef<any> => !!template) ? (templates as TemplateRef<any>[]) : [];
        }

        return [...this.panelChildren()];
    });

    /**
     * Resolved per-panel configuration (min/max/collapsible/collapsedSize/size).
     */
    panelMetas = computed<SplitterPanelMeta[]>(() => {
        const components = this.panelComponents();

        if (components && components.length) {
            return components.map((panel) => ({
                minSize: panel.minSize() ?? 0,
                maxSize: panel.maxSize() ?? 100,
                collapsible: panel.collapsible() ?? false,
                collapsedSize: panel.collapsedSize() ?? 0,
                size: panel.size()
            }));
        }

        const count = this.panelChildren().length;
        const minSizes = this.minSizes();
        const panelSizes = this.panelSizes();

        return Array.from({ length: count }, (_, i) => ({
            minSize: minSizes[i] ?? 0,
            maxSize: 100,
            collapsible: false,
            collapsedSize: 0,
            size: panelSizes[i]
        }));
    });

    /**
     * Value-based signature of the panel configuration. Lets the (re)initialization effect ignore
     * array-literal input bindings that change identity but not value on every parent change detection.
     */
    panelSignature = computed(() => {
        const metaSig = this.panelMetas()
            .map((meta) => `${meta.size ?? ''}:${meta.minSize}:${meta.maxSize}:${meta.collapsible}:${meta.collapsedSize}`)
            .join(',');

        return `${metaSig}#${this.panelSizes().join(',')}`;
    });

    /**
     * Class for each panel wrapper: the base panel class plus the splitter-level `panelStyleClass`
     * and the `class` set directly on the matching SplitterPanel.
     */
    panelClass = computed(() => {
        const components = this.panelComponents();
        const base = this.cn(this.cx('panel'), this.panelStyleClass());

        return this.panels().map((_, i) => this.cn(base, components[i]?.hostClass));
    });

    /**
     * Inline style for each panel wrapper: the `style` set directly on the matching SplitterPanel,
     * falling back to the splitter-level `panelStyle`.
     */
    panelInlineStyle = computed(() => {
        const components = this.panelComponents();
        const fallback = this.panelStyle();

        return this.panels().map((_, i) => components[i]?.hostStyle ?? fallback);
    });

    dragging: boolean = false;

    isResizing = signal(false);

    resizingIndex = signal<number | null>(null);

    collapsed = signal<boolean[]>([]);

    /**
     * Flex values applied to each panel wrapper, e.g. `35 1 0px`. Bound declaratively so panel sizing
     * never depends on imperative DOM timing.
     */
    panelFlex = signal<string[]>([]);

    dataResizing = computed(() => (this.isResizing() ? '' : null));

    pointerMoveListener: VoidListener;

    pointerUpListener: VoidListener;

    size: Nullable<number>;

    gutterElement: Nullable<ElementRef | HTMLElement>;

    startPos: Nullable<number>;

    _panelSizes: number[] = [];

    panelRegistry: SplitterPanelInfo[] = [];

    initialSizes: number[] = [];

    initialCollapsed: boolean[] = [];

    reportedCollapsed: boolean[] = [];

    initialTotal: number = 100;

    prevPanelIndex: Nullable<number>;

    timer: ReturnType<typeof setTimeout> | undefined;

    prevSize: string | undefined;

    _componentStyle = inject(SplitterStyle);

    rootClass = computed(() => this.cn(this.cx('root'), this.styleClass()));

    constructor() {
        super();
        effect(() => {
            // Re-initialize whenever the set of panels or their (value-based) size configuration changes.
            const panels = this.panels();
            this.panelSignature();

            if (!isPlatformBrowser(this.platformId) || panels.length === 0) {
                return;
            }

            // Never clobber sizes mid-drag; the resizing flag is read untracked so ending a drag
            // does not by itself re-trigger initialization.
            if (untracked(() => this.isResizing())) {
                return;
            }

            this.initializePanels();
        });
    }

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptms(['host', 'root']));
    }

    buildPanelRegistry() {
        const metas = this.panelMetas();
        const prev = this.panelRegistry ?? [];

        this.panelRegistry = metas.map((meta, i) => ({
            index: i,
            minSize: meta.minSize ?? 0,
            maxSize: meta.maxSize ?? 100,
            collapsible: meta.collapsible ?? false,
            collapsedSize: meta.collapsedSize ?? 0,
            size: meta.size,
            collapsed: prev[i]?.collapsed ?? false
        }));
    }

    initializePanels() {
        const panels = this.panels();

        if (!panels.length) {
            return;
        }

        this.buildPanelRegistry();

        let initialized = false;

        if (this.isStateful()) {
            initialized = this.restoreState();
        }

        if (!initialized) {
            const _panelSizes: number[] = [];
            const inputPanelSizes = this.panelSizes();

            panels.forEach((_, i) => {
                const meta = this.panelRegistry[i];
                // Splitter-level `panelSizes` takes precedence, then the panel's own `size`, then an equal split.
                _panelSizes[i] = inputPanelSizes[i] ?? meta?.size ?? 100 / panels.length;
            });

            this.panelRegistry.forEach((info, i) => {
                if (info?.collapsible) {
                    info.collapsed = _panelSizes[i] <= (info.collapsedSize ?? 0);
                }
            });

            this._panelSizes = _panelSizes;
            this.prevSize = parseFloat(String(_panelSizes[0])).toFixed(4);
        }

        this.syncCollapsedState();
        this.updateFlex();
    }

    updateFlex() {
        this.panelFlex.set(this._panelSizes.map((panelSize) => panelSize + ' 1 0px'));
    }

    syncCollapsedState() {
        this.collapsed.set(this.panelRegistry.map((info) => info.collapsed));
    }

    getPanelMinSize(index: number): number {
        return this.panelRegistry?.[index]?.minSize ?? 0;
    }

    getPanelMaxSize(index: number): number {
        return this.panelRegistry?.[index]?.maxSize ?? 100;
    }

    resizeStart(event: PointerEvent | KeyboardEvent, index: number, isKeyDown?: boolean) {
        const currentTarget = (event.currentTarget as HTMLElement) || (event.target as HTMLElement);

        if (currentTarget) {
            this.gutterElement = currentTarget;
        }

        const panelElements = (this.el as ElementRef).nativeElement.querySelectorAll(':scope > [data-index]');
        let totalPanelPx = 0;

        for (const el of panelElements) {
            const rect = el.getBoundingClientRect();
            totalPanelPx += this.horizontal() ? rect.width : rect.height;
        }

        this.size = totalPanelPx;

        if (!isKeyDown) {
            const pointerEvent = event as PointerEvent;

            this.dragging = true;
            this.startPos = this.horizontal() ? pointerEvent.pageX : pointerEvent.pageY;
            this.isResizing.set(true);
            this.resizingIndex.set(index);
        }

        this.initialSizes = [...this._panelSizes];
        this.initialCollapsed = this.panelRegistry.map((info) => info.collapsed);
        this.reportedCollapsed = this.panelRegistry.map((info) => info.collapsed);
        this.initialTotal = this.initialSizes.reduce((a, b) => a + b, 0) || 100;
        this.prevPanelIndex = index;

        if (!isKeyDown) {
            this.onResizeStart.emit({ originalEvent: event, sizes: [...this._panelSizes] });
        }
    }

    onResizeMove(event: PointerEvent | KeyboardEvent, step?: number, isKeyDown?: boolean) {
        if (this.size === null || this.prevPanelIndex === null || this.initialSizes.length === 0) {
            return;
        }

        const gutterIdx = this.prevPanelIndex!;
        const total = this.initialTotal;
        let delta: number;

        if (isKeyDown) {
            delta = (total * (step ?? 0)) / this.size!;
        } else {
            const pointerEvent = event as PointerEvent;
            const pos = this.horizontal() ? pointerEvent.pageX : pointerEvent.pageY;

            if (this.horizontal() && isRTL(this.el.nativeElement)) {
                delta = (((this.startPos ?? 0) - pos) * total) / this.size!;
            } else {
                delta = ((pos - (this.startPos ?? 0)) * total) / this.size!;
            }
        }

        const newSizes = [...this.initialSizes];

        this.panelRegistry.forEach((info, i) => {
            if (this.initialCollapsed[i] !== undefined) {
                info.collapsed = this.initialCollapsed[i];
            }
        });

        if (delta > 0) {
            this.distribute(newSizes, gutterIdx, delta, isKeyDown, 'forward');
        } else if (delta < 0) {
            this.distribute(newSizes, gutterIdx + 1, -delta, isKeyDown, 'backward');
        }

        this.panelRegistry.forEach((info, i) => {
            if (info.collapsed !== this.reportedCollapsed[i]) {
                this.reportedCollapsed[i] = info.collapsed;
                this.onCollapse.emit({ index: i, collapsed: info.collapsed, sizes: [...newSizes] });
            }
        });

        this._panelSizes = newSizes;
        this.prevSize = newSizes[gutterIdx].toFixed(4);

        this.updateFlex();
        this.syncCollapsedState();
        this.onResize.emit({ originalEvent: event, sizes: [...newSizes] });
    }

    distribute(newSizes: number[], growIdx: number, requested: number, isKeyDown: boolean | undefined, direction: 'forward' | 'backward') {
        const growInfo = this.panelRegistry[growIdx];
        const max = this.getPanelMaxSize(growIdx);
        let toGrow = Math.min(requested, Math.max(0, max - newSizes[growIdx]));

        if (growInfo?.collapsible && growInfo.collapsed) {
            // Re-open symmetrically: any outward drag/step pops a collapsed panel back to (at least) its minimum size.
            const gapSize = this.getPanelMinSize(growIdx) - growInfo.collapsedSize;

            toGrow = Math.max(toGrow, gapSize);
            toGrow = Math.min(toGrow, Math.max(0, max - newSizes[growIdx]));
        }

        let shrunk = 0;
        const range = direction === 'forward' ? this.range(growIdx + 1, newSizes.length, 1) : this.range(growIdx - 1, -1, -1);

        for (const i of range) {
            if (shrunk >= toGrow) break;

            const info = this.panelRegistry[i];
            const min = this.getPanelMinSize(i);

            if (info?.collapsed) continue;

            const effectiveMin = info?.collapsible ? (info.collapsedSize ?? 0) : min;
            const available = Math.max(0, newSizes[i] - effectiveMin);
            const amount = Math.min(toGrow - shrunk, available);
            const rawSize = newSizes[i] - amount;

            const validated = this.validatePanelSize(rawSize, info, min, isKeyDown);
            const actualShrunk = newSizes[i] - validated.size;

            newSizes[i] = validated.size;
            shrunk += actualShrunk;

            if (info) info.collapsed = validated.collapsed;
        }

        newSizes[growIdx] += shrunk;

        if (growInfo?.collapsible && growInfo.collapsed && newSizes[growIdx] >= this.getPanelMinSize(growIdx)) {
            growInfo.collapsed = false;
        }
    }

    validatePanelSize(rawSize: number, info: SplitterPanelInfo | undefined, min: number, isKeyDown: boolean | undefined): { size: number; collapsed: boolean } {
        if (!info?.collapsible) {
            return { size: Math.max(rawSize, min), collapsed: false };
        }

        const collapsedSize = info.collapsedSize ?? 0;

        if (rawSize >= min) {
            return { size: rawSize, collapsed: false };
        }

        // The panel stops shrinking at its minimum size; the moment the user keeps dragging (or
        // stepping) past that minimum, a collapsible panel snaps to its collapsed state.
        return { size: collapsedSize, collapsed: true };
    }

    range(start: number, end: number, step: number): number[] {
        const out: number[] = [];

        for (let i = start; step > 0 ? i < end : i > end; i += step) out.push(i);

        return out;
    }

    resizeEnd(event: PointerEvent | KeyboardEvent) {
        if (this.isStateful()) {
            this.saveState();
        }

        this.onResizeEnd.emit({ originalEvent: event, sizes: [...this._panelSizes] });
        this.isResizing.set(false);
        this.resizingIndex.set(null);
        this.updateFlex();
        this.clear();
    }

    onGutterPointerDown(event: PointerEvent, index: number) {
        if (this.disabled()) {
            return;
        }

        this.resizeStart(event, index);
        this.bindPointerListeners();
    }

    repeat(event: KeyboardEvent, index: number, step: number) {
        this.resizeStart(event, index, true);
        this.onResizeMove(event, step, true);
    }

    setTimer(event: KeyboardEvent, index: number, step: number) {
        if (!this.timer) {
            this.onResizeStart.emit({ originalEvent: event, sizes: [...this._panelSizes] });
            this.repeat(event, index, step);
            this.timer = setInterval(() => {
                this.repeat(event, index, step);
            }, 40);
        }
    }

    clearTimer() {
        if (this.timer) {
            clearInterval(this.timer);
            this.timer = undefined;
        }
    }

    onGutterKeyUp(event: KeyboardEvent) {
        if (!this.timer) return;
        this.clearTimer();
        this.resizeEnd(event);
    }

    onGutterKeyDown(event: KeyboardEvent, index: number) {
        if (this.disabled()) {
            return;
        }

        switch (event.code) {
            case 'ArrowLeft': {
                if (this.layout() === 'horizontal') {
                    this.setTimer(event, index, this.step() * -1);
                }

                event.preventDefault();
                break;
            }

            case 'ArrowRight': {
                if (this.layout() === 'horizontal') {
                    this.setTimer(event, index, this.step());
                }

                event.preventDefault();
                break;
            }

            case 'ArrowDown': {
                if (this.layout() === 'vertical') {
                    this.setTimer(event, index, this.step());
                }

                event.preventDefault();
                break;
            }

            case 'ArrowUp': {
                if (this.layout() === 'vertical') {
                    this.setTimer(event, index, this.step() * -1);
                }

                event.preventDefault();
                break;
            }

            default:
                //no op
                break;
        }
    }

    bindPointerListeners() {
        if (!this.pointerMoveListener) {
            this.pointerMoveListener = this.renderer.listen(this.document, 'pointermove', (event: PointerEvent) => {
                this.onResizeMove(event);
            });
        }

        if (!this.pointerUpListener) {
            this.pointerUpListener = this.renderer.listen(this.document, 'pointerup', (event: PointerEvent) => {
                this.resizeEnd(event);
                this.unbindPointerListeners();
            });
        }
    }

    unbindPointerListeners() {
        if (this.pointerMoveListener) {
            this.pointerMoveListener();
            this.pointerMoveListener = null;
        }

        if (this.pointerUpListener) {
            this.pointerUpListener();
            this.pointerUpListener = null;
        }
    }

    clear() {
        this.dragging = false;
        this.size = null;
        this.startPos = null;
        this.initialSizes = [];
        this.initialCollapsed = [];
        this.reportedCollapsed = [];
        this.initialTotal = 100;
        this.gutterElement = null;
        this.prevPanelIndex = null;
    }

    isStateful() {
        return this.stateKey() != null;
    }

    getStorage() {
        if (isPlatformBrowser(this.platformId)) {
            switch (this.stateStorage()) {
                case 'local':
                    return this.document.defaultView?.localStorage;

                case 'session':
                    return this.document.defaultView?.sessionStorage;

                default:
                    throw new Error(this.stateStorage() + ' is not a valid value for the state storage, supported values are "local" and "session".');
            }
        } else {
            throw new Error('Storage is not a available by default on the server.');
        }
    }

    saveState() {
        this.getStorage()?.setItem(this.stateKey()!, JSON.stringify(this._panelSizes));
    }

    restoreState() {
        const storage = this.getStorage();
        const stateString = storage?.getItem(this.stateKey()!);

        if (stateString) {
            this._panelSizes = JSON.parse(stateString);

            this.panelRegistry.forEach((info, i) => {
                if (info?.collapsible) {
                    info.collapsed = this._panelSizes[i] <= (info.collapsedSize ?? 0);
                }
            });

            this.prevSize = parseFloat(String(this._panelSizes[0])).toFixed(4);

            return true;
        }

        return false;
    }

    /**
     * Resets the panel sizes using the stored state (for a stateful Splitter), the configured
     * sizes, or the default equal distribution.
     */
    resetState() {
        this.initializePanels();
    }

    gutterInlineStyle() {
        return {
            'touch-action': 'none',
            'user-select': 'none',
            ...(this.horizontal() ? { width: this.gutterSize() + 'px' } : { height: this.gutterSize() + 'px' })
        };
    }

    horizontal() {
        return this.layout() === 'horizontal';
    }

    round(value: number | undefined): number {
        return Math.round(value ?? 0);
    }

    onDestroy() {
        this.unbindPointerListeners();
        this.clearTimer();
    }

    dataP = computed(() => {
        return this.cn({
            [this.layout()!]: this.layout(),
            resizing: this.isResizing(),
            disabled: this.disabled()
        });
    });
}

@NgModule({
    imports: [Splitter, SplitterPanel, SharedModule, BindModule],
    exports: [Splitter, SplitterPanel, SharedModule, BindModule]
})
export class SplitterModule {}
